describe('Save Search Query Feature', () => {
    beforeEach(() => {
        cy.visit('/search'); // Navigate to the search page
    });

    it('should save a search query successfully', () => {
        cy.get('input[name="search"]').type('Cypress testing'); // Enter search query
        cy.get('button[type="submit"]').click(); // Submit the search
        cy.get('.save-query-button').click(); // Click to save the query
        cy.get('.notification').should('contain', 'Search query saved successfully'); // Verify success message
    });

    it('should show an error when trying to save an empty query', () => {
        cy.get('button[type="submit"]').click(); // Submit without entering a query
        cy.get('.save-query-button').click(); // Attempt to save the empty query
        cy.get('.error-message').should('contain', 'Cannot save an empty query'); // Verify error message
    });
});
